import 'package:flutter_test/flutter_test.dart';
import 'package:moodledger/main.dart';
void main() { testWidgets('dashboard, consentimento e formulário de humor', (tester) async { await tester.pumpWidget(const MoodLedgerApp()); expect(find.text('Linha do tempo'), findsOneWidget); expect(find.text('Eventos próximos no tempo não provam causalidade.'), findsOneWidget); expect(find.text('Compartilhamento consentido'), findsOneWidget); await tester.tap(find.text('Registrar humor')); await tester.pumpAndSettle(); expect(find.text('Registrar estado mental'), findsOneWidget); expect(find.text('Horas de sono'), findsOneWidget); }); }
